insert into public.permissions(key,module,action,description,is_dangerous) values('finance_payments.reconcile','finance_payments','reconcile','Reconcile and confirm finance payments against bank evidence.',true) on conflict (key) do update set module=excluded.module,action=excluded.action,description=excluded.description,is_dangerous=excluded.is_dangerous;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.key='admin_finance_reporting' and p.key='finance_payments.reconcile' on conflict do nothing;
